        structure:{suelta:'Suelta',granular:'Granular',compacta:'Compacta',terronosa:'Terronosa',laminar:'Laminar',sin_evaluar:'Sin evaluar'},
        moisture:{seca:'Seca',adecuada:'Adecuada',humeda:'Húmeda',saturada:'Saturada',sin_evaluar:'Sin evaluar'},
        drainage:{bueno:'Bueno',lento:'Lento',encharcado:'Encharcado',excesivo:'Excesivo',sin_evaluar:'Sin evaluar'},
